.mapdoc-summary:hover { color: var(--text-2); }
.map-section { margin-top: 12px; }
.map-section-title {
  font-family: var(--mono);
  font-size: 10.5px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--accent-hi);
  margin-bottom: 6px;
}
/* nothing charted yet keeps the dashed placeholder; groups replace it */
.map-waypoints > .dim-line {
  padding: 18px;
  border: 1px dashed var(--hairline);
  border-radius: var(--radius-lg);
  text-align: center;
}

.wp-group { margin-bottom: 14px; }
.wp-group-title {
  font-family: var(--mono);
  font-size: 10.5px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--text-3);
  margin-bottom: 7px;
}
.wp-group-frontier .wp-group-title { color: var(--accent-hi); }
.wp-group-claimed .wp-group-title { color: var(--drive); }
details.wp-group-done { border-top: 1px solid var(--hairline-soft); padding-top: 12px; }
details.wp-group-done > summary { cursor: pointer; list-style: revert; }

.wp {
  display: flex;
  align-items: baseline;
  gap: 9px;
  flex-wrap: wrap;
  padding: 9px 12px;
  border: 1px solid var(--hairline);
  border-radius: var(--radius-sm);
  background: var(--panel-2);
  margin-bottom: 6px;
}
.wp-frontier { border-color: var(--accent-line); }
.wp-blocked { opacity: 0.55; }
.wp-claimed { border-color: color-mix(in srgb, var(--drive) 45%, var(--hairline)); }
.wp-done { opacity: 0.6; }

.wp-type {
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--text-2);
  border: 1px solid var(--hairline-strong);
  border-radius: var(--radius-sm);
  padding: 1px 6px;
  flex-shrink: 0;
}
/* The rail is only ~300px wide — a long title wraps rather than overflowing. */
.wp-title { color: var(--text); font-size: 13px; flex: 1; min-width: 0; overflow-wrap: anywhere; }
.wp-blockers, .wp-lineage, .wp-resume, .wp-summary {
  font-family: var(--mono);
  font-size: 11px;
  color: var(--text-3);
}
.wp-blockers { color: var(--needs); }
.wp-lineage { flex-basis: 100%; }
.wp-resume { color: var(--drive); }
/* AFK research run in flight on a claimed waypoint. */
.wp-run-note {
  font-family: var(--mono);
  font-size: 11px;
  color: var(--drive);
  font-style: italic;
}
/* Work / Resume sits at the right edge of the frontier row. */
.wp-work { margin-left: auto; align-self: center; flex-shrink: 0; }
.wp-pulse {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--drive);
  flex-shrink: 0;
  animation: pulse 1.4s ease-in-out infinite;
}

/* Converge re-entry (recovery, kept quiet): stranded at spec after a crash. */
.converge-resume {
  margin-top: 14px;
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  padding: 10px 14px;
  border: 1px solid var(--hairline);
  border-radius: var(--radius);
  background: var(--panel-2);
}
.converge-resume-text { font-size: 12.5px; color: var(--text-2); }

/* Convergence control (ADR-0001 §13.6): Converge button + soft fog warning. */
.converge-bar {
