   border: 1px solid var(--hairline);
   border-radius: var(--radius-sm);
   background: var(--panel-2);
   margin-bottom: 6px;
+  cursor: pointer;
+  transition: border-color var(--dur-2) var(--ease-out);
 }
+.wp:hover { border-color: var(--hairline-strong); }
 .wp-frontier { border-color: var(--accent-line); }
 .wp-blocked { opacity: 0.55; }
 .wp-claimed { border-color: color-mix(in srgb, var(--drive) 45%, var(--hairline)); }
 .wp-done { opacity: 0.6; }

+.wp-top {
+  display: flex;
+  align-items: baseline;
+  gap: 9px;
+}
