+  margin-top: 8px;
+  padding-top: 8px;
+  border-top: 1px solid var(--hairline-soft);
+  display: flex;
+  flex-direction: column;
+  gap: 6px;
+  cursor: default;
+}
+/* The question — the field this card exists to show — as rendered prose. */
