   font-family: var(--mono);
   font-size: 10px;
@@ -1298,14 +1324,15 @@ details.wp-group-done > summary { cursor: pointer; list-style: revert; }
 }
 /* The rail is only ~300px wide — a long title wraps rather than overflowing. */
 .wp-title { color: var(--text); font-size: 13px; flex: 1; min-width: 0; overflow-wrap: anywhere; }
-.wp-blockers, .wp-lineage, .wp-resume, .wp-summary {
