   color: var(--text-3);
 }
 .wp-blockers { color: var(--needs); }
-.wp-lineage { flex-basis: 100%; }
 .wp-resume { color: var(--drive); }
+/* Beats `.md`'s own colour — the resolution summary reads quieter than the question. */
+.wp-detail .wp-summary { color: var(--text-3); }
 /* AFK research run in flight on a claimed waypoint. */
 .wp-run-note {
   font-family: var(--mono);
@@ -1313,8 +1340,13 @@ details.wp-group-done > summary { cursor: pointer; list-style: revert; }
   color: var(--drive);
   font-style: italic;
 }
-/* Work / Resume sits at the right edge of the frontier row. */
-.wp-work { margin-left: auto; align-self: center; flex-shrink: 0; }
+/* Work / Resume owns the card's second line. */
+.wp-actions {
+  margin-top: 8px;
+  display: flex;
+  align-items: center;
+  gap: 7px;
+}
 .wp-pulse {
   width: 7px;
   height: 7px;
@@ -1324,6 +1356,23 @@ details.wp-group-done > summary { cursor: pointer; list-style: revert; }
   animation: pulse 1.4s ease-in-out infinite;
